package com.euvcraft.lithmod.core.multiblock;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;
class T5StructuresTest{
 private Map<MultiblockPos,BlockKind> cells(MultiblockDirection f,int column,int depth){var map=new HashMap<MultiblockPos,BlockKind>();int rx=switch(f){case NORTH->1;case SOUTH->-1;default->0;},rz=switch(f){case EAST->1;case WEST->-1;default->0;},bx=switch(f){case EAST->-1;case WEST->1;default->0;},bz=switch(f){case NORTH->1;case SOUTH->-1;default->0;};for(int u=0;u<2;u++)for(int v=0;v<2;v++)for(int d=0;d<depth;d++)map.put(new MultiblockPos(rx*(u-column)+bx*d,v,rz*(u-column)+bz*d),BlockKind.CASING);map.put(new MultiblockPos(0,0,0),BlockKind.CONTROLLER);return map;}
 @Test void bothSmallShapesAllOrientations(){for(var f:MultiblockDirection.values())for(int c=0;c<2;c++)for(int d=2;d<=3;d++){var map=cells(f,c,d);var spare=new ArrayList<>(map.keySet().stream().filter(p->!p.equals(new MultiblockPos(0,0,0))).sorted(Comparator.comparing(MultiblockPos::toString)).toList());map.put(spare.get(0),BlockKind.POWER_PORT);if(d==3){map.put(spare.get(1),BlockKind.WATER_INLET);map.put(spare.get(2),BlockKind.FLUID_OUTLET);}var result=d==2?AssemblyStructureMatcher.match(new MultiblockPos(0,0,0),f,p->map.getOrDefault(p,BlockKind.OTHER)):UtilityStructureMatcher.match(new MultiblockPos(0,0,0),f,p->map.getOrDefault(p,BlockKind.OTHER));assertTrue(result.success(),f+" "+c+" "+d);assertEquals(4*d,result.memberPositions().size());map.put(spare.get(0),BlockKind.CASING);assertFalse((d==2?AssemblyStructureMatcher.match(new MultiblockPos(0,0,0),f,p->map.getOrDefault(p,BlockKind.OTHER)):UtilityStructureMatcher.match(new MultiblockPos(0,0,0),f,p->map.getOrDefault(p,BlockKind.OTHER))).success());}}
 @Test void utilityRequiresDistinctPorts(){var map=cells(MultiblockDirection.NORTH,0,3);map.put(new MultiblockPos(1,0,0),BlockKind.POWER_PORT);map.put(new MultiblockPos(1,1,1),BlockKind.WATER_INLET);assertFalse(UtilityStructureMatcher.match(new MultiblockPos(0,0,0),MultiblockDirection.NORTH,p->map.getOrDefault(p,BlockKind.OTHER)).success());map.put(new MultiblockPos(1,1,2),BlockKind.FLUID_OUTLET);assertTrue(UtilityStructureMatcher.match(new MultiblockPos(0,0,0),MultiblockDirection.NORTH,p->map.getOrDefault(p,BlockKind.OTHER)).success());map.put(new MultiblockPos(0,1,2),BlockKind.FLUID_OUTLET);assertFalse(UtilityStructureMatcher.match(new MultiblockPos(0,0,0),MultiblockDirection.NORTH,p->map.getOrDefault(p,BlockKind.OTHER)).success());}
}

